const graphs=[['mogreps850','850hPa temperature'],['mogrepstmp','1.5m temperature'],['mogrepstmp_max','1.5m maximum temperature'],['mogrepstmp_min','1.5m minimum temperature'],['mogrepsrr','Rain rate'],['mogrepswg','Wind gusts'],['mogrepssr','Snow rate'],['mogrepssd','Snow depth'],['mogrepsmslp','Mean sea level pressure']];
const stamps=[['850_temp','850hPa temperature'],['1_5m_temp','1.5m temperature'],['rain_rate','Rain rate'],['gust_wind','Wind gusts'],['snow_rate','Snow rate'],['snow_depth','Snow depth'],['mslp','Mean sea level pressure'],['mslp500','500hPa heights / MSLP']];
const locations=['London','Aberdeen','Belfast','Berkhamsted','Birmingham','Brighton','Cairngorms','Cardiff','Carlisle','Edinburgh','Glasgow','Inverness','Leeds','Liverpool','Manchester','Newcastle','Norwich','Nottingham','Peterborough','Plymouth','Reading','Sheffield','Snowdonia','York','Amsterdam','Berlin','Dublin','Frankfurt','Oslo','Paris','Rome','Warsaw'].map(name=>({name,id:({Amsterdam:'amsterdam_netherlands',Berlin:'berlin_germany',Frankfurt:'frankfurt_germany',Oslo:'oslo_norway',Paris:'paris_france',Rome:'rome_italy',Warsaw:'warsaw_poland'})[name]||name.toLowerCase()}));
const $=id=>document.getElementById(id);const params=new URLSearchParams(location.search);
let mode=params.get('view')==='stamps'?'stamps':'graphs',graph=graphs.some(v=>v[0]===params.get('graph'))?params.get('graph'):'mogreps850',stamp=stamps.some(v=>v[0]===params.get('stamp'))?params.get('stamp'):'850_temp',secondStamp=stamps.some(v=>v[0]===params.get('second'))?params.get('second'):'mslp',comparing=mode==='stamps'&&params.get('compare')==='1',hour=params.has('hour')&&Number.isFinite(Number(params.get('hour')))?Math.min(198,Math.max(0,Math.round(Number(params.get('hour'))/3)*3)):144,timer=null,refreshKey='',requests={'':0,'2':0};
locations.forEach(l=>$('location').add(new Option(l.name,l.id)));$('location').value=locations.some(l=>l.id===params.get('location'))?params.get('location'):'leeds';if(['00','06','12','18'].includes(params.get('run')))$('run').value=params.get('run');stamps.forEach(([id,name])=>$('second-variable').add(new Option(name,id)));
let controlsHidden=params.get('controls')==='hidden',sizing=['width','whole','actual'].includes(params.get('size'))?params.get('size'):(controlsHidden?'whole':'width');
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play';$('play').setAttribute('aria-pressed','false')}
function chartUrl(variable){const run=$('run').value;return 'https://www.theweatheroutlook.com/charts/mogreps/'+(run==='latest'?'':run+'/')+(mode==='graphs'?variable+$('location').value:variable+'_'+hour+'_ps')+'.png'}
function updateVariables(){const selected=mode==='graphs'?graph:stamp,ukOnly=['mogrepstmp_max','mogrepstmp_min'],isUK=locations.findIndex(l=>l.id===$('location').value)<24;$('variable').replaceChildren();(mode==='graphs'?graphs:stamps).forEach(([id,name])=>{const option=new Option(name+(ukOnly.includes(id)?' · UK':''),id);option.disabled=mode==='graphs'&&ukOnly.includes(id)&&!isUK;$('variable').add(option)});if(mode==='graphs'&&ukOnly.includes(graph)&&!isUK)graph='mogrepstmp';$('variable').value=mode==='graphs'?graph:stamp}
function render(){if(mode==='graphs')comparing=false;updateVariables();document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('location-control').hidden=mode==='stamps';$('timeline').hidden=mode==='graphs';$('second-control').hidden=!comparing;$('second-slot').hidden=!comparing;$('chart-grid').classList.toggle('comparing',comparing);$('compare').textContent=comparing?'Single chart':'Compare stamps';$('compare').setAttribute('aria-pressed',String(comparing));$('variable-label').textContent=comparing?'Left chart':'Forecast variable';$('second-variable').value=secondStamp;$('hour').value=hour;$('hour-text').textContent='+'+hour+'h';$('previous').disabled=hour===0;$('next').disabled=hour===198;document.querySelectorAll('[data-hour]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.hour)===hour)));const run=$('run').value==='latest'?'Latest available run':$('run').value+'Z run';$('subtitle').textContent=(mode==='graphs'?locations.find(l=>l.id===$('location').value).name+' · Full forecast period':'UK postage stamps · +'+hour+' hours')+' · '+run;$('help').textContent=mode==='graphs'?'Each line is an ensemble member. A wider spread means more uncertainty.':'Each map is an ensemble member at the same forecast time. Compare the maps to see the range of possible outcomes.';const q=new URLSearchParams({view:mode,graph,stamp,location:$('location').value,run:$('run').value,hour:String(hour)});if(comparing){q.set('compare','1');q.set('second',secondStamp)}q.set('size',sizing);if(controlsHidden)q.set('controls','hidden');history.replaceState(null,'','?'+q);loadChart('',mode==='graphs'?graph:stamp);if(comparing)loadChart('2',secondStamp);else requests['2']++;requestAnimationFrame(sizeCharts)}
function loadChart(suffix,variable){const seq=++requests[suffix],image=$('chart'+suffix),name=(mode==='graphs'?graphs:stamps).find(v=>v[0]===variable)[1],url=chartUrl(variable);$('title'+suffix).textContent=name;$('original'+suffix).href=url;$('fallback'+suffix).href='https://www.theweatheroutlook.com/twodata/mogreps.aspx?run=mr-'+($('run').value==='latest'?'na':$('run').value)+(mode==='graphs'?'&type='+variable+'&location='+$('location').value:'&pstype='+variable+'&hour='+hour);$('status'+suffix).textContent='Loading source chart…';$('error'+suffix).hidden=true;image.style.visibility='hidden';const candidate=new Image();candidate.referrerPolicy='no-referrer';candidate.onload=()=>{if(seq!==requests[suffix])return;image.src=candidate.src;image.alt=name+(mode==='graphs'?' ensemble for '+$('location').selectedOptions[0].text:' postage stamps at +'+hour+' hours');image.hidden=false;image.style.visibility='visible';$('status'+suffix).textContent='';$('loaded').textContent='Image loaded at '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})+' · Charts © TheWeatherOutlook · Data: Met Office';requestAnimationFrame(sizeCharts)};candidate.onerror=()=>{if(seq!==requests[suffix])return;stop();image.hidden=true;$('status'+suffix).textContent='';$('error'+suffix).hidden=false};candidate.src=url+(refreshKey?'?refresh='+refreshKey:'')}
function sizeCharts(){const scroll=$('chart-scroll');const top=scroll.getBoundingClientRect().top+window.scrollY;document.documentElement.style.setProperty('--viewer-height',Math.max(260,window.innerHeight-top-(controlsHidden?8:44))+'px');const grid=$('chart-grid'),gridStyle=getComputedStyle(grid);grid.classList.toggle('actual',sizing==='actual');for(const suffix of ['', '2']){const image=$('chart'+suffix),panel=$('panel'+suffix);if(!image.naturalWidth||panel.closest('article').hidden)continue;const css=getComputedStyle(panel);const available=panel.clientWidth-parseFloat(css.paddingLeft)-parseFloat(css.paddingRight);let scale=sizing==='actual'?1:Math.min(1,available/image.naturalWidth);if(sizing==='whole'){const heading=panel.previousElementSibling.getBoundingClientRect().height;const availableHeight=scroll.clientHeight-parseFloat(gridStyle.paddingTop)-parseFloat(gridStyle.paddingBottom)-heading-parseFloat(css.paddingTop)-parseFloat(css.paddingBottom)-6;scale=Math.min(scale,Math.max(80,availableHeight)/image.naturalHeight)}image.style.width=Math.floor(image.naturalWidth*scale)+'px'}}
function applyLayout(){document.body.classList.toggle('controls-hidden',controlsHidden);$('chart-selections').hidden=controlsHidden;$('toggle-controls').textContent=controlsHidden?'Show selections':'Hide selections';$('toggle-controls').setAttribute('aria-expanded',String(!controlsHidden));$('size').value=sizing;const q=new URLSearchParams(location.search);q.set('size',sizing);if(controlsHidden)q.set('controls','hidden');else q.delete('controls');history.replaceState(null,'','?'+q);sizeCharts();$('chart-scroll').scrollTop=0}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{stop();mode=b.dataset.mode;render()});$('location').onchange=$('run').onchange=()=>{stop();render()};$('variable').onchange=()=>{stop();if(mode==='graphs')graph=$('variable').value;else stamp=$('variable').value;render()};$('second-variable').onchange=()=>{stop();secondStamp=$('second-variable').value;render()};$('compare').onclick=()=>{stop();comparing=!comparing;if(comparing){mode='stamps';stamp='rain_rate';secondStamp='mslp'}render()};$('hour').oninput=()=>{stop();hour=Number($('hour').value);render()};$('previous').onclick=()=>{stop();hour=Math.max(0,hour-3);render()};$('next').onclick=()=>{stop();hour=Math.min(198,hour+3);render()};$('play').onclick=()=>{if(timer){stop();return}timer=setInterval(()=>{hour=hour>=198?0:hour+3;render()},1800);$('play').textContent='Pause';$('play').setAttribute('aria-pressed','true')};[0,24,48,72,96,120,144,168,198].forEach(h=>{const b=document.createElement('button');b.textContent='+'+h+'h';b.dataset.hour=h;b.onclick=()=>{stop();hour=h;render()};document.querySelector('.jumps').append(b)});$('size').onchange=()=>{sizing=$('size').value;applyLayout()};$('toggle-controls').onclick=()=>{controlsHidden=!controlsHidden;if(controlsHidden)sizing='whole';applyLayout()};$('refresh').onclick=$('retry').onclick=$('retry2').onclick=()=>{stop();refreshKey=Date.now();render()};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('resize',sizeCharts);new ResizeObserver(sizeCharts).observe(document.querySelector('.toolbar'));new ResizeObserver(sizeCharts).observe($('chart-grid'));$('chart').onload=$('chart2').onload=sizeCharts;render();

applyLayout();

function syncFullscreen(){const active=Boolean(document.fullscreenElement);$('fullscreen').textContent=active?'Exit full screen':'Full screen';$('fullscreen').setAttribute('aria-pressed',String(active));$('fullscreen').title=active?'Exit full screen (Esc)':'Expand the viewer to fill your screen';requestAnimationFrame(sizeCharts)}
$('fullscreen').onclick=async()=>{const message=$('fullscreen-message');message.hidden=true;try{if(document.fullscreenElement){await document.exitFullscreen()}else if(document.documentElement.requestFullscreen&&document.fullscreenEnabled){await document.documentElement.requestFullscreen()}else{message.textContent='Full screen is unavailable in this browser or embedded view. Open the viewer in a browser tab to use it.';message.hidden=false}}catch{message.textContent='The browser could not enter full screen. Try opening the viewer in its own browser tab.';message.hidden=false}syncFullscreen()};document.addEventListener('fullscreenchange',syncFullscreen);syncFullscreen();
